"""Saved-result SAC capacity-repair report, no collection."""
import json
from fractions import Fraction
from collect_smollm_v47 import ROOT,read,write

def summarize_comparators(arms):
 comparisons={};modes=sorted({m for a in arms for m in a['references']})
 for m in modes:
  available=[a for a in arms if m in a['references']];gs=[(Fraction(str(a['references'][m]))-Fraction(str(a['target'])))/Fraction(str(a['references'][m])) for a in available];comparisons[m]={'cases':len(available),'mean_fraction':str(sum(gs)/len(gs)),'mean_percent':float(sum(gs)/len(gs)*100),'wins':sum(g>0 for g in gs),'ties':sum(g==0 for g in gs),'losses':sum(g<0 for g in gs)}
 return comparisons

def main():
 out=ROOT/'results/v135_analysis';s=read(out/'summary.json');assert s['complete'];arms=s['arms'];ledger=read(ROOT/'results/v135_proposals/ledger.json');raw=[json.loads(x) for x in (ROOT/'results/v135_proposals/responses.jsonl').read_text().splitlines()];modes=sorted({m for a in arms for m in a['references']});comparisons={}
 comparisons=summarize_comparators(arms)
 usage={'generated_observed':sum(r['response'].get('tokens_predicted',0) for r in raw),'prefill_observed':sum(r['response'].get('tokens_evaluated',0) for r in raw),'missing_usage':ledger['generation_requests']-sum(type(r['response'].get('tokens_predicted')) is int and type(r['response'].get('tokens_evaluated')) is int for r in raw)};result={'scope':'Same-prompt exposed SAC capacity repair; not a new held-out group or replacement of old failures','intended':5,'valid':sum(a['model_status']=='valid' for a in arms),'fallbacks':sum(a['fallback'] for a in arms),'improved_prefix':sum(a['target']<a['prefix_best'] for a in arms),'comparisons':comparisons,'usage':usage,'ledger':ledger,'new_recorded_acquisitions':s['new_recorded_acquisitions'],'evaluation_seconds':s['evaluation_seconds'],'rows':[{'seed':a['seed'],'prefix_best':a['prefix_best'],'new_target':a['target'],'old_fallback_target':a['old_failed_contract_target'],'sequential_target':a['references']['full_sequential_3nn'],'valid':a['model_status']=='valid','gain_vs_sequential':a['gains']['full_sequential_3nn']} for a in arms]};write(out/'comparison.json',result)
 lines=['# V135: does a valid SAC response repair the optimization result?','','Five exposed-development cases, identical historical B10 prefixes and prompt bytes, same original sampling seeds. The model/runtime identity is unchanged. This repair changes the output allowance from512 to1024 and uses the V128 canonical grammar; it does not isolate token count from whitespace grammar. The59-feature format has a constructive622-token upper bound including EOS. Original V127 failures and V134 denominator remain intact.','', f"Actual new responses: {result['valid']}/5 valid, {result['fallbacks']} fallbacks; {result['improved_prefix']}/5 improve the saved prefix.",'', '| Comparator | Available cases | Mean new model gain | Wins/ties/losses |','|---|---:|---:|---:|']
 for m,r in comparisons.items():lines.append(f"|{m}|{r['cases']}|{r['mean_percent']:+.4f}%|{r['wins']}/{r['ties']}/{r['losses']}|")
 lines+=['','| Seed | Prefix | Old fallback | New model | Sequential |','|---:|---:|---:|---:|---:|']
 for r in result['rows']:lines.append(f"|{r['seed']}|{r['prefix_best']}|{r['old_fallback_target']}|{r['new_target']}|{r['sequential_target']}|")
 lines += ['', f"Actual costs: {ledger['generation_requests']} real requests, {ledger['retries']} retries, {ledger['allocated_output_tokens']} allocated output tokens; {usage['generated_observed']} generated / {usage['prefill_observed']} prefill observed, {usage['missing_usage']} missing-usage attempts. Model lifecycle {ledger['stage_seconds']:.3f}s, startup {ledger.get('startup_seconds',float('nan')):.3f}s; peak sampled server RSS {ledger['peak_server_rss_bytes']}bytes, exit {ledger['server_exit_code']}. Exactly {s['new_recorded_acquisitions']} newly charged table accesses in {s['evaluation_seconds']:.3f}s; five B20 arms each preserve ten acquired prefix labels. All choices sealed before targets were parsed. No new native run, download or spending.",'','Every primary comparison retains all five cases. The optional historical single-portfolio control exists for only a subset of seeds; its actual denominator is explicit and cannot support a five-seed contrast. Historical classical/random controls are reused with identical prefix state and hashes; their original collection cost is not zero or charged again as new native execution. Deployment estimate is one request and ten new outcomes per escalation, total B20, plus startup/projection overhead. This table is recorded n-body execution-time data: original equal-utility, measurement-noise and dataset-redistribution limitations remain unresolved; no new functional correctness validation is implied. Historical source metadata may retain its original split label; this stage is explicitly exposed development.','', 'This is a reliability repair, not a new independent family, a fitted router or journal-ready result. Valid output need not create incremental optimization benefit. Do not overwrite failed-contract evidence or add these five repeats as five new systems. Reproduce with `scripts/report_repair_v135.py`; full source/acquisition/response replay uses `scripts/verify_repair_v135.py`.']
 (ROOT/'reports/repair_v135.md').write_text('\n'.join(lines)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
